            "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}},
    }


MULTI_FLAG = [False]


def build(brief):
    multi = brief.upper() == "B"
    MULTI_FLAG[0] = multi
    return {
        "initial_node": "setup",
        "system_prompt": SYSTEM,
        "nodes": {
