        {"queue": {"type": "string", "enum": allowed, "default": "{{queue}}", "description": "One of: " + ", ".join(allowed) + "."}},
        ["queue"],
        pre=sub(TRANSFER_PRE, False),
        post=sub(TRANSFER_POST, False),
